package com.campus.secondhand.trading.chat;
import jakarta.persistence.LockModeType;import java.util.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface ChatConversationRepository extends JpaRepository<ChatConversation,Long>{Optional<ChatConversation>findByItemIdAndBuyerIdAndSellerId(Long item,Long buyer,Long seller);Optional<ChatConversation>findByPublicId(String id);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select c from ChatConversation c where c.publicId=:id")Optional<ChatConversation>findLocked(@Param("id")String id);@Query("select c from ChatConversation c where c.buyerId=:actor or c.sellerId=:actor order by coalesce(c.lastMessageAt,c.createdAt) desc,c.id desc")Page<ChatConversation>forActor(@Param("actor")Long actor,Pageable page);@Query("select c from ChatConversation c where c.buyerId=:actor or c.sellerId=:actor")List<ChatConversation>allForActor(@Param("actor")Long actor);}
